import { AbstractSubgraphEndpoint } from 'uniswap/src/constants/abstractContracts'

export interface FetchSubgraphOptions<TVariables = Record<string, any>> {
  query: string
  variables?: TVariables
  operationName?: string
  signal?: AbortSignal
  fetchImpl?: typeof fetch
  requestId?: string
}

export interface FetchSubgraphErrorContext {
  status: number
  statusText: string
  url: string
  body?: unknown
}

export class SubgraphRequestError extends Error {
  context: FetchSubgraphErrorContext

  constructor(message: string, context: FetchSubgraphErrorContext) {
    super(message)
    this.name = 'SubgraphRequestError'
    this.context = context
  }
}

/**
 * Shared helper for executing GraphQL requests against Abstract subgraphs.
 * Applies endpoint-specific headers, handles JSON parsing, and normalizes errors.
 */
export async function fetchFromSubgraph<TData, TVariables = Record<string, any>>(
  endpoint: AbstractSubgraphEndpoint,
  options: FetchSubgraphOptions<TVariables>,
): Promise<TData> {
  const { query, variables, operationName, signal, fetchImpl, requestId } = options

  const requestBody = JSON.stringify({
    query,
    variables,
    operationName,
  })

  const headers = {
    'Content-Type': 'application/json',
    ...(endpoint.headers ?? {}),
  }

  const execFetch = fetchImpl ?? fetch

  const response = await execFetch(endpoint.url, {
    method: 'POST',
    headers,
    body: requestBody,
    signal,
  })

  let payload: any = null
  try {
    payload = await response.json()
  } catch (error) {
    throw new SubgraphRequestError(`Subgraph response was not valid JSON${requestId ? ` [${requestId}]` : ''}`, {
      status: response.status,
      statusText: response.statusText,
      url: endpoint.url,
    })
  }

  if (!response.ok) {
    throw new SubgraphRequestError(
      `Subgraph request failed with status ${response.status}${requestId ? ` [${requestId}]` : ''}`,
      {
        status: response.status,
        statusText: response.statusText,
        url: endpoint.url,
        body: payload,
      },
    )
  }

  if (payload?.errors?.length) {
    const messages = payload.errors.map((error: any) => error?.message ?? 'Unknown error').join(', ')
    throw new SubgraphRequestError(
      `Subgraph returned errors: ${messages}${requestId ? ` [${requestId}]` : ''}`,
      {
        status: response.status,
        statusText: response.statusText,
        url: endpoint.url,
        body: payload,
      },
    )
  }

  return payload?.data as TData
}
