type AbstractFeeData = {
  gasPriceWei: bigint
  maxFeePerGasWei: bigint
  maxPriorityFeePerGasWei: bigint
}

const FEE_REFRESH_INTERVAL_MS = 12_000
const DEFAULT_PRIORITY_FEE_WEI = 1_000_000_000n
const DEFAULT_FALLBACK_GAS_PRICE_WEI = 3_000_000_000n

export function useWrapTransactionRequestInfo({
  derivedSwapInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  account?: AccountMeta
}): TransactionRequestInfo {
  const isWrapApplicable = getIsWrapApplicable({ derivedSwapInfo })
  const isAbstract = isAbstractChain(derivedSwapInfo.chainId)
  const wrapTxRequest = useWrapTransactionRequest(derivedSwapInfo, account)
  const abstractFeeData = useAbstractFeeData(isAbstract ? derivedSwapInfo.chainId : undefined)
  const apiGasFeeResult = useTransactionGasFee(
    wrapTxRequest,
    !isWrapApplicable || isAbstract,
    undefined,
    WRAP_FALLBACK_GAS_LIMIT_IN_GWEI * 10e9,
  ) // Skip Gas Fee API call on transactions that don't need wrapping

  const gasFeeResult = useMemo<GasFeeResult>(() => {
    if (!isAbstract) {
      return apiGasFeeResult
    }

    if (!wrapTxRequest || !isWrapApplicable) {
      return {
        value: undefined,
        displayValue: undefined,
        error: null,
        isLoading: false,
        gasEstimates: undefined,
      }
    }

    if (!abstractFeeData) {
      return {
        value: undefined,
        displayValue: undefined,
        error: null,
        isLoading: true,
        gasEstimates: undefined,
      }
    }

    const gasLimitBigInt = (() => {
      const gasLimit = wrapTxRequest.gasLimit
      if (gasLimit == null) {
        return BigInt(WRAP_FALLBACK_GAS_LIMIT_IN_GWEI)
      }
      if (typeof gasLimit === 'string') {
        return BigInt(gasLimit)
      }
      if (typeof gasLimit === 'number') {
        return BigInt(Math.trunc(gasLimit))
      }
      return BigInt(gasLimit.toString())
    })()

    const gasLimitString = gasLimitBigInt.toString()
    const gasFeeWei = (gasLimitBigInt * abstractFeeData.maxFeePerGasWei).toString()

    return {
      value: gasFeeWei,
      displayValue: gasFeeWei,
      error: null,
      isLoading: false,
      params: {
        maxFeePerGas: toRpcHex(abstractFeeData.maxFeePerGasWei),
        maxPriorityFeePerGas: toRpcHex(abstractFeeData.maxPriorityFeePerGasWei),
        gasLimit: toRpcHex(gasLimitBigInt),
      },
      gasEstimates: {
        activeEstimate: {
          type: FeeType.EIP1559,
          maxFeePerGas: abstractFeeData.maxFeePerGasWei.toString(),
          maxPriorityFeePerGas: abstractFeeData.maxPriorityFeePerGasWei.toString(),
          gasLimit: gasLimitString,
          gasFee: gasFeeWei,
          strategy: DEFAULT_GAS_STRATEGY,
        },
        shadowEstimates: [],
      },
    }
  }, [abstractFeeData, apiGasFeeResult, isAbstract, isWrapApplicable, wrapTxRequest])

  const result = useMemo(() => processWrapResponse({ gasFeeResult, wrapTxRequest }), [gasFeeResult, wrapTxRequest])

  const cachedGasFeeResultRef = useRef(gasFeeResult)
  if (gasFeeResult.value) {
    cachedGasFeeResultRef.current = gasFeeResult
  }

  // Wrap gas cost should not change significantly between trades, so we can use the last value if current is unavailable.
  const resultWithCaching = useMemo(() => {
    const value = result.gasFeeResult.value ?? cachedGasFeeResultRef.current.value
    const displayValue = result.gasFeeResult.displayValue ?? cachedGasFeeResultRef.current.displayValue

    const gasFeeResultWithCaching = {
      ...result.gasFeeResult,
      value,
      displayValue,
    }

    return { ...result, gasFeeResult: gasFeeResultWithCaching }
  }, [result])

  return resultWithCaching
}

// Abstract DEX transaction request info hook
function useAbstractTransactionRequestInfo({
  derivedSwapInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  account?: AccountMeta
}): TransactionRequestInfo {
  const { customDeadline, customSlippageTolerance, autoSlippageTolerance } = useTransactionSettingsContext()

  // Initialize our clean service architecture
  const swapRouter = useMemo(() => new AbstractSwapRouter(), [])

  // Check if wallet supports EIP-5792 batching
  const supportsEip5792 = useEip5792Support(derivedSwapInfo.chainId)

  // Fetch current gas / fee data from the blockchain
  const abstractFeeData = useAbstractFeeData(derivedSwapInfo.chainId)
  const currentGasPrice = abstractFeeData?.gasPriceWei.toString()

  // Get approval info to determine if batching is needed
  const approvalInfo = useTokenApprovalInfo({
    chainId: derivedSwapInfo.chainId,
    wrapType: derivedSwapInfo.wrapType,
    currencyInAmount: derivedSwapInfo.currencyAmounts.input,
    routing: derivedSwapInfo.trade.routing,
    account,
    trade: derivedSwapInfo.trade
  })

  const txRequests = useMemo(() => {
    const { trade, chainId, currencyAmounts } = derivedSwapInfo
    
    if (!account?.address || !isAbstractChain(chainId) || !trade.trade) {
      return undefined
    }

    // Get user settings
    const deadline = getTradeSettingsDeadline(customDeadline) || (Math.floor(Date.now() / 1000) + 1800)
    const slippageValue = customSlippageTolerance || autoSlippageTolerance || 0.5
    const slippageTolerance = Math.floor(slippageValue * 100) // Convert to basis points

    const needsApproval = approvalInfo.tokenApprovalInfo.action === ApprovalAction.Permit2Approve
    
    // Use batching only when approval is needed AND wallet supports EIP-5792
    if (needsApproval && supportsEip5792) {
      // EIP-5792 batching: approval + swap in one transaction
      // Use exact approval amount when batching (safer since approval + swap execute atomically)
      const inputAmount = currencyAmounts[CurrencyField.INPUT]
      return swapRouter.buildBatchedTransaction({
        trade,
        currencyAmounts,
        chainId,
        account,
        slippageTolerance,
        deadline,
        needsApproval: true,
        approvalAmount: inputAmount?.quotient.toString(), // Exact amount for batched transactions
        // Pass original currencies to preserve ETH intent
        originalCurrencies: derivedSwapInfo.currencies,
      })
    } else {
      // Fallback to single swap transaction
      // When batching is not supported, approvals will be handled separately by the saga
      const swapTx = swapRouter.buildSwapTransaction({
        trade,
        currencyAmounts,
        chainId,
        account,
        slippageTolerance,
        deadline,
        // Pass original currencies to preserve ETH intent
        originalCurrencies: derivedSwapInfo.currencies,
      })
      return swapTx ? [swapTx] : undefined
    }
  }, [
    derivedSwapInfo, 
    account, 
    customDeadline, 
    customSlippageTolerance, 
    autoSlippageTolerance, 
    swapRouter,
    approvalInfo.tokenApprovalInfo.action,
    supportsEip5792
  ])

  // Use Abstract DEX gas estimation with dynamic gas price from blockchain
  const gasFeeResult = useMemo(() => {
    if (!txRequests || !isAbstractChain(derivedSwapInfo.chainId)) {
      return {
        value: undefined,
        displayValue: undefined,
        error: null,
        isLoading: false,
        gasEstimates: undefined,
      }
    }

    // Wait for gas price to be fetched
    if (!currentGasPrice) {
      return {
        value: undefined,
        displayValue: undefined,
        error: null,
        isLoading: true,
        gasEstimates: undefined,
      }
    }

    // Calculate gas based on batching support and approval needs
    const needsApproval = approvalInfo.tokenApprovalInfo.action === ApprovalAction.Permit2Approve
    const willBatch = needsApproval && supportsEip5792

    // Gas estimation:
    // - Single swap: 200k gas
    // - Batched approval + swap: 250k gas
    // - Non-batched with approval: 200k gas (approval handled separately)
    const gasLimitEstimate = willBatch ? 250000 : 200000

    // Use dynamic gas price from blockchain
    const gasPriceBigInt = BigInt(currentGasPrice)
    const gasFeeWei = (BigInt(gasLimitEstimate) * gasPriceBigInt).toString()

    return {
      value: gasFeeWei,
      displayValue: gasFeeWei,
      error: null,
      isLoading: false,
      gasEstimates: {
        activeEstimate: {
          strategy: 'standard' as const,
          gasLimit: gasLimitEstimate.toString(),
          gasFee: gasFeeWei,
          gasCostUSD: undefined, // Let the UI calculate USD value
        },
        shadowEstimates: [],
      },
    }
  }, [txRequests, derivedSwapInfo.chainId, approvalInfo.tokenApprovalInfo.action, supportsEip5792, currentGasPrice])

  return useMemo(() => {
    const needsApproval = approvalInfo.tokenApprovalInfo.action === ApprovalAction.Permit2Approve
    const willBatch = needsApproval && supportsEip5792

    const gasEstimate = {
      swapEstimates: gasFeeResult.gasEstimates || [{
        strategy: 'standard' as const,
        gasLimit: willBatch ? '250000' : '200000',
        gasCostUSD: undefined, // Let the UI calculate USD value dynamically
      }],
    }

    return {
      gasFeeResult,
      txRequests: txRequests,
      gasEstimate,
      swapRequestArgs: undefined,
    }
  }, [gasFeeResult, txRequests, approvalInfo.tokenApprovalInfo.action, supportsEip5792])
}

export function useTransactionRequestInfo({
  derivedSwapInfo,
  tokenApprovalInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  tokenApprovalInfo: TokenApprovalInfo | undefined
  account?: AccountMeta
}): TransactionRequestInfo {
  const wrapTransactionRequestInfo = useWrapTransactionRequestInfo({
    derivedSwapInfo,
    account,
  })

  const abstractTransactionRequestInfo = useAbstractTransactionRequestInfo({
    derivedSwapInfo,
    account
  })

  const isWrapApplicable = getIsWrapApplicable({ derivedSwapInfo })


  // Handle wrapping (ETH <-> WETH)
  if (isWrapApplicable) {
    return wrapTransactionRequestInfo
  }

  // All other trades go through Abstract DEX
  return abstractTransactionRequestInfo
}

function useAbstractFeeData(chainId: number | undefined): AbstractFeeData | undefined {
  const provider = useEthersProvider({ chainId })
  const [feeData, setFeeData] = useState<AbstractFeeData | undefined>(undefined)

  useEffect(() => {
    if (!provider || !chainId || !isAbstractChain(chainId)) {
      setFeeData(undefined)
      return
    }

    let cancelled = false

    const fetchFeeData = async () => {
      try {
        const feeDataResponse = await provider.getFeeData()
        const sanitizedFeeData = sanitizeFeeData(feeDataResponse)
        if (!cancelled) {
          setFeeData(sanitizedFeeData)
        }
      } catch (error) {
        try {
          const gasPrice = await provider.getGasPrice()
          if (!cancelled) {
            setFeeData(createFeeDataFromGasPrice(BigInt(gasPrice.toString())))
          }
        } catch {
          if (!cancelled) {
            setFeeData(createFeeDataFromGasPrice(DEFAULT_FALLBACK_GAS_PRICE_WEI))
          }
        }
      }
    }

    fetchFeeData()
    const interval = setInterval(fetchFeeData, FEE_REFRESH_INTERVAL_MS)

    return () => {
      cancelled = true
      clearInterval(interval)
    }
  }, [chainId, provider])

  return feeData
}

function sanitizeFeeData(feeData: providers.FeeData): AbstractFeeData {
  const gasPrice = toBigInt(feeData.gasPrice) ?? DEFAULT_FALLBACK_GAS_PRICE_WEI
  const maxFee = toBigInt(feeData.maxFeePerGas) ?? gasPrice
  const maxPriority = toBigInt(feeData.maxPriorityFeePerGas) ?? DEFAULT_PRIORITY_FEE_WEI

  const normalizedMaxFee = maxFee >= maxPriority ? maxFee : maxPriority
  const normalizedPriorityFee = maxPriority <= normalizedMaxFee ? maxPriority : normalizedMaxFee
  const normalizedGasPrice = gasPrice > 0n ? gasPrice : normalizedMaxFee

  return {
    gasPriceWei: normalizedGasPrice,
    maxFeePerGasWei: normalizedMaxFee,
    maxPriorityFeePerGasWei: normalizedPriorityFee,
  }
}

function createFeeDataFromGasPrice(gasPriceWei: bigint): AbstractFeeData {
  const normalizedGasPrice = gasPriceWei > 0n ? gasPriceWei : DEFAULT_FALLBACK_GAS_PRICE_WEI
  const normalizedPriorityFee =
    normalizedGasPrice >= DEFAULT_PRIORITY_FEE_WEI ? DEFAULT_PRIORITY_FEE_WEI : normalizedGasPrice

  return {
    gasPriceWei: normalizedGasPrice,
    maxFeePerGasWei: normalizedGasPrice,
    maxPriorityFeePerGasWei: normalizedPriorityFee,
  }
}

function toBigInt(value: providers.FeeData['gasPrice']): bigint | undefined {
  if (!value) {
    return undefined
  }

  try {
    return BigInt(value.toString())
  } catch {
    return undefined
  }
}

function toRpcHex(value: bigint): string {
  return `0x${value.toString(16)}`
}
