import { BigNumber, ethers } from 'ethers'
import { CurrencyAmount, TradeType } from '@uniswap/sdk-core'
import { CurrencyField } from 'uniswap/src/types/currency'

export interface V2TransactionParams {
  inputAmount: CurrencyAmount<any>
  outputAmount: CurrencyAmount<any>
  path: string[]
  pairs: any[]
  tradeType: TradeType
  slippageTolerance: number // in basis points
  deadline: number
  recipient: string
  shouldInputEth: boolean
  shouldOutputEth: boolean
  factoryAddress: string
  hasFeeOnTransfer?: boolean // true if any token in the swap has fee-on-transfer (tax)
}

export interface V2TransactionResult {
  calldata: string
  value: string
  targetRouter: string
  success: boolean
  error?: string
}

export class V2TransactionBuilder {
  
  /**
   * Build V2 exact input transaction
   */
  buildExactInputTransaction(params: V2TransactionParams): V2TransactionResult {
    try {
      const {
        inputAmount,
        outputAmount,
        path,
        pairs,
        slippageTolerance,
        deadline,
        recipient,
        shouldInputEth,
        shouldOutputEth,
        factoryAddress,
        hasFeeOnTransfer = false
      } = params

      const amountIn = inputAmount.quotient.toString()
      const amountOutMin = this.calculateMinimumOutput(outputAmount, slippageTolerance)
      const routes = this.buildRoutes(path, pairs, factoryAddress)

      if (shouldInputEth && !shouldOutputEth) {
        return this.buildETHToTokenTransaction(amountOutMin, routes, recipient, deadline, amountIn, hasFeeOnTransfer)
      } else if (!shouldInputEth && shouldOutputEth) {
        return this.buildTokenToETHTransaction(amountIn, amountOutMin, routes, recipient, deadline, hasFeeOnTransfer)
      } else {
        return this.buildTokenToTokenTransaction(amountIn, amountOutMin, routes, recipient, deadline, hasFeeOnTransfer)
      }
    } catch (error) {
      return {
        calldata: '',
        value: '0',
        targetRouter: '',
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      }
    }
  }

  /**
   * Build V2 exact output transaction (uses approximation since Aerodrome doesn't support exact output)
   */
  buildExactOutputTransaction(params: V2TransactionParams): V2TransactionResult {
    // For exact output, we use the input amount from our corrected quotes
    // and apply conservative slippage to the desired output
    const modifiedParams = {
      ...params,
      tradeType: TradeType.EXACT_INPUT // Convert to exact input
    }
    
    // Use more conservative slippage for exact output approximation
    const conservativeSlippage = Math.max(params.slippageTolerance, 100) // At least 1%
    const modifiedParamsWithSlippage = {
      ...modifiedParams,
      slippageTolerance: conservativeSlippage
    }

    return this.buildExactInputTransaction(modifiedParamsWithSlippage)
  }

  private calculateMinimumOutput(outputAmount: CurrencyAmount<any>, slippageTolerance: number): string {
    return BigNumber.from(outputAmount.quotient.toString())
      .mul(10000 - slippageTolerance)
      .div(10000)
      .toString()
  }

  private buildRoutes(path: string[], pairs: any[], factoryAddress: string) {
    const routes = []
    
    for (let i = 0; i < path.length - 1; i++) {
      // Get stable flag from the corresponding pair
      const stable = pairs[i] && (pairs[i] as any).stable ? true : false
      
      routes.push({
        from: path[i],
        to: path[i + 1],
        stable,
        factory: factoryAddress
      })
    }
    
    return routes
  }

  private buildETHToTokenTransaction(
    amountOutMin: string,
    routes: any[],
    recipient: string,
    deadline: number,
    value: string,
    hasFeeOnTransfer: boolean = false
  ): V2TransactionResult {
    // Use fee-on-transfer supporting function if any token in the swap has fee-on-transfer
    const functionName = hasFeeOnTransfer
      ? 'swapExactETHForTokensSupportingFeeOnTransferTokens'
      : 'swapExactETHForTokens'

    const iface = new ethers.utils.Interface([
      `function ${functionName}(uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)`
    ])

    const calldata = iface.encodeFunctionData(functionName, [
      amountOutMin, routes, recipient, deadline
    ])

    return {
      calldata,
      value,
      targetRouter: '', // Will be set by caller
      success: true
    }
  }

  private buildTokenToETHTransaction(
    amountIn: string,
    amountOutMin: string,
    routes: any[],
    recipient: string,
    deadline: number,
    hasFeeOnTransfer: boolean = false
  ): V2TransactionResult {
    // Use fee-on-transfer supporting function if any token in the swap has fee-on-transfer
    const functionName = hasFeeOnTransfer
      ? 'swapExactTokensForETHSupportingFeeOnTransferTokens'
      : 'swapExactTokensForETH'

    const iface = new ethers.utils.Interface([
      `function ${functionName}(uint256 amountIn, uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)`
    ])

    const calldata = iface.encodeFunctionData(functionName, [
      amountIn, amountOutMin, routes, recipient, deadline
    ])

    return {
      calldata,
      value: '0',
      targetRouter: '', // Will be set by caller
      success: true
    }
  }

  private buildTokenToTokenTransaction(
    amountIn: string,
    amountOutMin: string,
    routes: any[],
    recipient: string,
    deadline: number,
    hasFeeOnTransfer: boolean = false
  ): V2TransactionResult {
    // Use fee-on-transfer supporting function if any token in the swap has fee-on-transfer
    const functionName = hasFeeOnTransfer
      ? 'swapExactTokensForTokensSupportingFeeOnTransferTokens'
      : 'swapExactTokensForTokens'

    const iface = new ethers.utils.Interface([
      `function ${functionName}(uint256 amountIn, uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)`
    ])

    const calldata = iface.encodeFunctionData(functionName, [
      amountIn, amountOutMin, routes, recipient, deadline
    ])

    return {
      calldata,
      value: '0',
      targetRouter: '', // Will be set by caller
      success: true
    }
  }
}