import { Currency, CurrencyAmount } from '@uniswap/sdk-core'
import { useMemo } from 'react'
import { useUniswapContextSelector } from 'uniswap/src/contexts/UniswapContext'
import { Routing } from 'uniswap/src/data/tradingApi/__generated__/index'
import { AccountMeta } from 'uniswap/src/features/accounts/types'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { GasFeeResult } from 'uniswap/src/features/gas/types'
import { ApprovalAction, TokenApprovalInfo } from 'uniswap/src/features/transactions/swap/types/trade'
import { isUniswapX } from 'uniswap/src/features/transactions/swap/utils/routing'
import { WrapType } from 'uniswap/src/features/transactions/types/wrap'
import { isAbstractChain, getAbstractContracts } from 'uniswap/src/constants/abstractContracts'
import { useReadContract } from 'wagmi'
import { Address } from 'viem'
import { ethers } from 'ethers'
import { ClassicTrade } from 'state/routing/types'
import { useEip5792Support } from './useEip5792Support'

export interface TokenApprovalInfoParams {
  chainId: UniverseChainId
  wrapType: WrapType
  currencyInAmount: Maybe<CurrencyAmount<Currency>>
  currencyOutAmount?: Maybe<CurrencyAmount<Currency>>
  routing: Routing | undefined
  account?: AccountMeta
  trade?: ClassicTrade  // Add trade parameter to determine V2 vs V3
}

export type ApprovalTxInfo = {
  tokenApprovalInfo: TokenApprovalInfo
  approvalGasFeeResult: GasFeeResult
  revokeGasFeeResult: GasFeeResult
}

function useApprovalWillBeBatchedWithSwap(chainId: UniverseChainId, routing: Routing | undefined): boolean {
  // Check if wallet supports EIP-5792 batching
  const supportsEip5792 = useEip5792Support(chainId)
  const isBatchableFlow = Boolean(routing && !isUniswapX({ routing }))

  // Only batch when wallet supports EIP-5792 and flow is batchable
  return supportsEip5792 && isBatchableFlow
}

// ERC20 ABI for allowance function
const ERC20_ABI = [
  {
    name: 'allowance',
    type: 'function',
    stateMutability: 'view',
    inputs: [
      { name: 'owner', type: 'address' },
      { name: 'spender', type: 'address' }
    ],
    outputs: [{ name: '', type: 'uint256' }]
  },
  {
    name: 'approve',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [
      { name: 'spender', type: 'address' },
      { name: 'amount', type: 'uint256' }
    ],
    outputs: [{ name: '', type: 'bool' }]
  }
] as const

export function useTokenApprovalInfo(params: TokenApprovalInfoParams): ApprovalTxInfo {
  const { account, chainId, wrapType, currencyInAmount, routing, trade } = params

  const isWrap = wrapType !== WrapType.NotApplicable
  const address = account?.address
  const currencyIn = currencyInAmount?.currency
  const amount = currencyInAmount?.quotient.toString()
  const approvalWillBeBatchedWithSwap = useApprovalWillBeBatchedWithSwap(chainId, routing)

  // Get Abstract contracts
  const abstractContracts = getAbstractContracts(chainId)
  
  // Determine router based on trade type (V2 vs V3)
  // Handle both standard Uniswap and Abstract DEX trade structures
  const tradeObject = trade?.trade  // Standard Uniswap nested structure
  
  // Check for routes in both locations
  const hasV2Routes = (tradeObject?.v2Routes && tradeObject.v2Routes.length > 0) || 
                      (trade?.v2Routes && trade.v2Routes.length > 0)
  const hasV3Routes = (tradeObject?.v3Routes && tradeObject.v3Routes.length > 0) || 
                      (trade?.v3Routes && trade.v3Routes.length > 0)
  
  // Check for Abstract custom V3 structure
  const isCustomV3Trade = (tradeObject as any)?.isV3 === true || 
                          (trade as any)?.isV3 === true
  
  const isV3Trade = hasV3Routes || isCustomV3Trade
  
  // Select appropriate router address
  const routerAddress = isV3Trade 
    ? abstractContracts?.swapRouter  // V3 router for V3 trades
    : abstractContracts?.router      // V2 router for V2 trades
  
  // Only log when we have a trade but no route detection (skip when trade is still loading)
  if (trade && trade.trade !== null && !trade.isLoading && !hasV3Routes && !hasV2Routes && !isCustomV3Trade) {
    console.warn('TokenApprovalInfo: No routes detected after trade loaded', {
      hasV2Routes,
      hasV3Routes,
      isCustomV3Trade,
      tradeLoaded: trade.trade !== null,
      isLoading: trade.isLoading,
      routing: trade?.routing
    })
  }

  // Check current allowance using contract call
  const { data: currentAllowance, isLoading: allowanceLoading } = useReadContract({
    address: currencyIn?.isToken ? (currencyIn.address as Address) : undefined,
    abi: ERC20_ABI,
    functionName: 'allowance',
    args: address && routerAddress ? [address as Address, routerAddress as Address] : undefined,
    query: {
      enabled: Boolean(
        isAbstractChain(chainId) && 
        !isWrap && 
        address && 
        currencyIn?.isToken && 
        routerAddress && 
        amount && 
        !approvalWillBeBatchedWithSwap
      )
    }
  })

  const tokenApprovalInfo: TokenApprovalInfo = useMemo(() => {
    // Approval is N/A for wrap transactions, unconnected state, or batched swaps
    if (isWrap || !address || approvalWillBeBatchedWithSwap) {
      return {
        action: ApprovalAction.None,
        txRequest: null,
        cancelTxRequest: null,
      }
    }

    // For non-Abstract chains or native tokens, skip approval
    if (!isAbstractChain(chainId) || !currencyIn?.isToken) {
      return {
        action: ApprovalAction.None,
        txRequest: null,
        cancelTxRequest: null,
      }
    }

    // If we don't have the router address, can't determine approval
    if (!routerAddress) {
      return {
        action: ApprovalAction.Unknown,
        txRequest: null,
        cancelTxRequest: null,
      }
    }

    // If still loading allowance, return unknown
    if (allowanceLoading) {
      return {
        action: ApprovalAction.Unknown,
        txRequest: null,
        cancelTxRequest: null,
      }
    }

    // Check if approval is needed
    const needsApproval = currentAllowance !== undefined && 
                         amount && 
                         BigInt(currentAllowance.toString()) < BigInt(amount)



    if (!needsApproval) {
      return {
        action: ApprovalAction.None,
        txRequest: null,
        cancelTxRequest: null,
      }
    }

    // Create approval transaction request
    // Always approve max amount to avoid multiple approvals
    const MAX_UINT256 = '0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff'
    const approvalTxRequest = {
      to: currencyIn.address,
      data: new ethers.utils.Interface(ERC20_ABI).encodeFunctionData('approve', [
        routerAddress,
        MAX_UINT256 // Approve maximum amount to avoid repeated approvals
      ]),
      value: '0',
      from: address,
      chainId: chainId, // Required for validateTransactionRequest
    }

    return {
      action: ApprovalAction.Permit2Approve,
      txRequest: approvalTxRequest,
      cancelTxRequest: null,
    }
  }, [
    address, 
    approvalWillBeBatchedWithSwap, 
    isWrap, 
    chainId, 
    currencyIn, 
    routerAddress, 
    allowanceLoading, 
    currentAllowance, 
    amount,
    trade?.trade  // Depend on the nested trade object
  ])

  return useMemo(() => {
    const noApprovalNeeded = tokenApprovalInfo.action === ApprovalAction.None
    const unknownApproval = tokenApprovalInfo.action === ApprovalAction.Unknown
    const isGasLoading = unknownApproval && allowanceLoading
    const approvalGasError = unknownApproval && !allowanceLoading ? new Error('Approval action unknown') : null

    // Hardcoded gas fees for Abstract chains - 1 gwei
    const approvalGasLimit = 50000 // Gas limit for approval transaction
    const gasPrice = 1000000000 // 1 gwei in wei
    const approvalGasFee = (approvalGasLimit * gasPrice).toString()
    
    const approvalFee = noApprovalNeeded ? '0' : approvalGasFee
    const revokeFee = '0' // No revoke needed for our simple approval flow

    return {
      tokenApprovalInfo,
      approvalGasFeeResult: {
        value: approvalFee,
        displayValue: approvalFee,
        isLoading: isGasLoading,
        error: approvalGasError,
        gasEstimates: undefined,
        activeEstimate: undefined,
      },
      revokeGasFeeResult: {
        value: revokeFee,
        displayValue: revokeFee,
        isLoading: isGasLoading,
        error: null, // No revoke error
      },
    }
  }, [tokenApprovalInfo, allowanceLoading])
}
