"use strict";
import { useQuery } from "@tanstack/react-query";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const CHAIN_ID_TO_DEXSCREENER = {
  [UniverseChainId.Mainnet]: "abstract",
  [UniverseChainId.AbstractTestnet]: "abstract"
};
const MAX_PAIRS_PER_REQUEST = 30;
export function useDexScreenerPools(poolAddresses, chainId) {
  return useQuery({
    queryKey: ["dexscreener-pools", chainId, poolAddresses],
    queryFn: async () => {
      const dexScreenerChainId = CHAIN_ID_TO_DEXSCREENER[chainId];
      if (!dexScreenerChainId || poolAddresses.length === 0) {
        return /* @__PURE__ */ new Map();
      }
      const normalizedAddresses = poolAddresses.map((a) => a.toLowerCase());
      const poolMap = /* @__PURE__ */ new Map();
      const batches = [];
      for (let i = 0; i < normalizedAddresses.length; i += MAX_PAIRS_PER_REQUEST) {
        batches.push(normalizedAddresses.slice(i, i + MAX_PAIRS_PER_REQUEST));
      }
      const results = await Promise.all(
        batches.map(async (batch) => {
          const addresses = batch.join(",");
          const url = `https://api.dexscreener.com/latest/dex/pairs/${dexScreenerChainId}/${addresses}`;
          const response = await fetch(url);
          if (!response.ok) {
            console.warn(`DexScreener API error for batch: ${response.status}`);
            return null;
          }
          const data = await response.json();
          return data.pairs ?? [];
        })
      );
      results.forEach((pairs) => {
        if (pairs) {
          pairs.forEach((pair) => {
            poolMap.set(pair.pairAddress.toLowerCase(), pair);
          });
        }
      });
      return poolMap;
    },
    enabled: poolAddresses.length > 0 && Boolean(CHAIN_ID_TO_DEXSCREENER[chainId]),
    staleTime: 6e4,
    // 60 seconds
    refetchInterval: 12e4,
    // 2 minutes
    retry: 2
  });
}
