import { TradeType, CurrencyAmount } from '@uniswap/sdk-core'
import { ethers } from 'ethers'
import { AccountMeta } from 'uniswap/src/features/accounts/types'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { getAbstractContracts, FEE_TO_TICK_SPACING } from 'uniswap/src/constants/abstractContracts'
import { isTokenFeeOnTransfer } from 'uniswap/src/constants/tokens'
import { CurrencyField } from 'uniswap/src/types/currency'
import { V2TransactionBuilder, V2TransactionParams } from './V2TransactionBuilder'
import { V3TransactionBuilder, V3TransactionParams } from './V3TransactionBuilder'

export interface SwapTransactionRequest {
  to: string
  data: string
  value: string
  from: string
  chainId: number
}

export interface SwapRouterParams {
  trade: any // Trade object
  currencyAmounts: { [field in CurrencyField]?: CurrencyAmount<any> }
  chainId: UniverseChainId
  account: AccountMeta
  slippageTolerance: number // in basis points
  deadline: number
  needsApproval?: boolean // Flag to indicate if approval is needed
  approvalAmount?: string // Amount for approval (usually max uint256)
  originalCurrencies?: { [field in CurrencyField]?: any } // Original user-selected currencies to preserve ETH intent
}

export class AbstractSwapRouter {
  private v2Builder: V2TransactionBuilder
  private v3Builder: V3TransactionBuilder

  constructor() {
    this.v2Builder = new V2TransactionBuilder()
    this.v3Builder = new V3TransactionBuilder()
  }

  /**
   * Build batched transactions (approval + swap) for EIP-5792
   */
  buildBatchedTransaction(params: SwapRouterParams): SwapTransactionRequest[] | null {
    if (!params.needsApproval) {
      const swapTx = this.buildSwapTransaction(params)
      if (!swapTx) return null
      // Swap transaction may already include unwrap via router multicall (V3 ETH-out).
      return [swapTx]
    }

    try {
      const { currencyAmounts, chainId, account } = params
      const inputAmount = currencyAmounts[CurrencyField.INPUT]

      if (!inputAmount?.currency.isToken || !account?.address) {
        return null
      }

      const abstractContracts = getAbstractContracts(chainId)
      if (!abstractContracts) {
        throw new Error('Abstract contracts not found for chain')
      }

      // Determine router address based on trade type
      const hasV3Routes = params.trade.trade?.v3Routes && params.trade.trade.v3Routes.length > 0
      const isCustomV3Trade = (params.trade.trade as any)?.isV3 === true
      const isV3Trade = hasV3Routes || isCustomV3Trade
      const routerAddress = isV3Trade ? abstractContracts.swapRouter : abstractContracts.router

      // Build approval transaction
      const MAX_UINT256 = '0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff'
      const approvalTx: SwapTransactionRequest = {
        to: inputAmount.currency.address,
        data: new ethers.utils.Interface([
          'function approve(address spender, uint256 amount) external returns (bool)'
        ]).encodeFunctionData('approve', [routerAddress, params.approvalAmount || MAX_UINT256]),
        value: '0',
        from: account.address,
        chainId
      }

      // Build swap transaction
      const swapTx = this.buildSwapTransaction(params)
      if (!swapTx) {
        throw new Error('Failed to build swap transaction')
      }
      // Swap transaction may already include unwrap via router multicall (V3 ETH-out).
      return [approvalTx, swapTx]

    } catch (error) {
      console.error('AbstractSwapRouter: Failed to build batched transaction', error)
      return null
    }
  }

  /**
   * Build swap transaction based on trade type and protocol
   */
  buildSwapTransaction(params: SwapRouterParams): SwapTransactionRequest | null {
    try {
      const { trade, currencyAmounts, chainId, account, slippageTolerance, deadline } = params

      if (!trade.trade || !account?.address) {
        return null
      }

      const abstractContracts = getAbstractContracts(chainId)
      if (!abstractContracts) {
        throw new Error('Abstract contracts not found for chain')
      }

      const inputAmount = currencyAmounts[CurrencyField.INPUT]
      const outputAmount = currencyAmounts[CurrencyField.OUTPUT]

      if (!inputAmount || !outputAmount) {
        return null
      }

      // Additional validation to prevent parameter corruption after approval
      if (!inputAmount.quotient || !outputAmount.quotient) {
        console.warn('AbstractSwapRouter: Currency amounts missing quotient values, skipping transaction build')
        return null
      }

      // Validate trade object is not corrupted
      if (!trade.trade) {
        console.warn('AbstractSwapRouter: Trade object is null/undefined, skipping transaction build')
        return null
      }

      // Determine trade type and protocol
      const isV2Trade = this.isV2Trade(trade.trade)
      const isV3Trade = this.isV3Trade(trade.trade)
      const tradeType = trade.trade.tradeType || TradeType.EXACT_INPUT

      if (!isV2Trade && !isV3Trade) {
        console.warn('AbstractSwapRouter: No valid V2 or V3 route found in trade', {
          hasV2Routes: trade.trade.v2Routes?.length > 0,
          hasV3Routes: trade.trade.v3Routes?.length > 0,
          isCustomV3: (trade.trade as any).isV3 === true
        })
        return null
      }

      // Extract path from trade
      const path = this.extractPath(trade.trade, isV2Trade)

      // Determine ETH handling using original currencies if available, fallback to trade currencies
      const inputCurrency = params.originalCurrencies?.[CurrencyField.INPUT]?.currency || inputAmount.currency
      const outputCurrency = params.originalCurrencies?.[CurrencyField.OUTPUT]?.currency || outputAmount.currency

      const { shouldInputEth, shouldOutputEth } = this.determineETHHandling(
        inputCurrency, outputCurrency, abstractContracts.weth
      )

      let result

      if (isV2Trade) {
        // Build V2 transaction
        const v2Route = trade.trade.v2Routes[0]
        const pairs = v2Route.routev2?.pairs || []

        // Check if any token in the swap has fee-on-transfer
        // This requires using special router functions that support fee-on-transfer tokens
        const hasFeeOnTransfer = isTokenFeeOnTransfer(inputCurrency) || isTokenFeeOnTransfer(outputCurrency)

        const v2Params: V2TransactionParams = {
          inputAmount,
          outputAmount,
          path,
          pairs,
          tradeType,
          slippageTolerance,
          deadline,
          recipient: account.address,
          shouldInputEth,
          shouldOutputEth,
          factoryAddress: abstractContracts.poolFactory,
          hasFeeOnTransfer
        }

        if (tradeType === TradeType.EXACT_INPUT) {
          result = this.v2Builder.buildExactInputTransaction(v2Params)
        } else {
          result = this.v2Builder.buildExactOutputTransaction(v2Params)
        }

        result.targetRouter = abstractContracts.router

      } else if (isV3Trade) {
        // Build V3 transaction
        const fees = this.extractV3Fees(trade.trade)
        const tickSpacing = this.extractTickSpacing(trade.trade)
        const tickSpacings = this.extractV3TickSpacings(trade.trade, fees)
        console.log('[V3Routing] Build V3 tx', { path, fees, tickSpacing, tickSpacings, tradeType })

        // If output should be ETH, route swap output to router, then unwrap via multicall
        const v3Recipient = shouldOutputEth ? abstractContracts.swapRouter : account.address

        const v3Params: V3TransactionParams = {
          inputAmount,
          outputAmount,
          path,
          fees,
          tradeType,
          tickSpacing,
          tickSpacings,
          slippageTolerance,
          deadline,
          recipient: v3Recipient,
          shouldInputEth,
          shouldOutputEth
        }

        if (tradeType === TradeType.EXACT_INPUT) {
          result = this.v3Builder.buildExactInputTransaction(v3Params)
        } else {
          result = this.v3Builder.buildExactOutputTransaction(v3Params)
        }

        result.targetRouter = abstractContracts.swapRouter

        // If ETH is requested as output, wrap swap + unwrap in router multicall
        if (shouldOutputEth) {
          const iface = new ethers.utils.Interface([
            'function unwrapWETH9(uint256 amountMinimum, address recipient)',
            'function multicall(bytes[] data) returns (bytes[] results)'
          ])

          // Unwrap all WETH held by router to ETH for the user; amountMinimum = 0
          const unwrapCalldata = iface.encodeFunctionData('unwrapWETH9', [0, account.address])
          const multicallData = iface.encodeFunctionData('multicall', [[result.calldata, unwrapCalldata]])

          // Replace result calldata with multicall; keep value as-is for ETH input cases
          result.calldata = multicallData
        }
      }

      if (!result || !result.success) {
        throw new Error(result?.error || 'Failed to build transaction')
      }

      return {
        to: result.targetRouter,
        data: result.calldata,
        value: result.value,
        from: account.address,
        chainId
      }

    } catch (error) {
      // Surface error details to help debug disabled swap button (txRequests undefined)
      console.error('[V3Routing] AbstractSwapRouter.buildSwapTransaction failed', error)
      return null
    }
  }

  private isV2Trade(trade: any): boolean {
    const hasV2Routes = trade.v2Routes && trade.v2Routes.length > 0
    const isCustomV3Trade = (trade as any).isV3 === true
    return hasV2Routes && !isCustomV3Trade
  }

  private isV3Trade(trade: any): boolean {
    const hasV3Routes = trade.v3Routes && trade.v3Routes.length > 0
    const isCustomV3Trade = (trade as any).isV3 === true
    return hasV3Routes || isCustomV3Trade
  }

  private extractPath(trade: any, isV2Trade: boolean): string[] {
    if (isV2Trade) {
      const v2Route = trade.v2Routes[0]
      if (v2Route.routev2?.path) {
        return v2Route.routev2.path.map((token: any) => token.address)
      }
    } else {
      // V3 trade
      const isCustomV3Trade = (trade as any).isV3 === true

      if (isCustomV3Trade) {
        const v3Quote = (trade as any).v3Quote
        if (Array.isArray(v3Quote?.path) && v3Quote.path.length >= 2) {
          return v3Quote.path
        }
        if (v3Quote?.tokenIn && v3Quote?.tokenOut) {
          return [v3Quote.tokenIn.address, v3Quote.tokenOut.address]
        }
      } else {
        const v3Route = trade.v3Routes[0]
        if (v3Route.routev3?.tokenPath) {
          return v3Route.routev3.tokenPath.map((token: any) => token.address)
        }
      }
    }

    throw new Error('Could not extract path from trade')
  }

  private extractV3Fees(trade: any): number[] | undefined {
    const isCustomV3Trade = (trade as any).isV3 === true
    if (isCustomV3Trade) {
      const v3Quote = (trade as any).v3Quote
      if (Array.isArray(v3Quote?.fees) && v3Quote.fees.length > 0) {
        return v3Quote.fees
      }
    } else {
      const v3Route = trade.v3Routes?.[0]
      const fees = v3Route?.routev3?.pools?.map((p: any) => p?.fee).filter((f: any) => typeof f === 'number')
      if (fees && fees.length > 0) return fees
    }
    return undefined
  }

  private extractTickSpacing(trade: any): number {
    const isCustomV3Trade = (trade as any).isV3 === true

    if (isCustomV3Trade) {
      const v3Quote = (trade as any).v3Quote
      return v3Quote?.tickSpacing || 200
    } else {
      const v3Route = trade.v3Routes[0]
      return v3Route.routev3?.pools?.[0]?.tickSpacing || 200
    }
  }

  // Extract per-hop tick spacings for multihop paths when available
  private extractV3TickSpacings(trade: any, fees?: number[]): number[] | undefined {
    try {
      const isCustomV3Trade = (trade as any).isV3 === true
      if (isCustomV3Trade) {
        const v3Quote = (trade as any).v3Quote
        if (Array.isArray(v3Quote?.tickSpacings) && v3Quote.tickSpacings.length > 0) {
          return v3Quote.tickSpacings
        }
        // Fallback: derive from fees when present
        if (Array.isArray(v3Quote?.fees) && v3Quote.fees.length > 0) {
          return v3Quote.fees.map((f: number) => (FEE_TO_TICK_SPACING as any)[f] ?? 200)
        }
      } else {
        // Standard V3 route object may not expose tickSpacing; derive from fees if provided
        if (Array.isArray(fees) && fees.length > 0) {
          return fees.map((f) => (FEE_TO_TICK_SPACING as any)[f] ?? 200)
        }
        const v3Route = trade.v3Routes?.[0]
        const perPoolTs: number[] | undefined = v3Route?.routev3?.pools
          ?.map((p: any) => p?.tickSpacing)
          ?.filter((ts: any) => typeof ts === 'number')
        if (perPoolTs && perPoolTs.length > 0) return perPoolTs
      }
    } catch {}
    return undefined
  }

  private determineETHHandling(
    inputCurrency: any,
    outputCurrency: any,
    wethAddress?: string
  ): { shouldInputEth: boolean; shouldOutputEth: boolean } {
    const shouldInputEth = Boolean(inputCurrency.isNative)
    const shouldOutputEth = Boolean(outputCurrency.isNative)

    return { shouldInputEth, shouldOutputEth }
  }

  /**
   * Build WETH unwrap transaction for ETH output
   */
  private buildUnwrapTransaction(params: SwapRouterParams): SwapTransactionRequest | null {
    try {
      const { currencyAmounts, chainId, account } = params
      const outputAmount = currencyAmounts[CurrencyField.OUTPUT]

      if (!outputAmount || !account?.address) {
        return null
      }

      const abstractContracts = getAbstractContracts(chainId)
      if (!abstractContracts?.weth) {
        return null
      }

      // Build WETH.withdraw(amount) transaction
      const wethInterface = new ethers.utils.Interface([
        'function withdraw(uint256 amount) external'
      ])

      const withdrawAmount = outputAmount.quotient.toString()
      const calldata = wethInterface.encodeFunctionData('withdraw', [withdrawAmount])

      return {
        to: abstractContracts.weth,
        data: calldata,
        value: '0',
        from: account.address,
        chainId
      }

    } catch (error) {
      console.error('AbstractSwapRouter: Failed to build unwrap transaction', error)
      return null
    }
  }
}
